Here is a fully functional, browser-based Memory Game called **"Space Catcher"**.

You can copy the code below, save it as an `.html` file (e.g., `memory-game.html`), and open it in any web browser to play. It works on both desktop and mobile!

### The Game: Space Catcher 🚀
**Goal:** Flip over two space characters at a time. If they match, they stay face up. If not, they flip back. Clear the board to win!

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Space Catcher Memory Game</title>
    <style>
        :root {
            --bg-color: #1a1a2e;
            --card-bg: #16213e;
            --accent: #e94560;
            --text: #ffffff;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: var(--bg-color);
            color: var(--text);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
            margin: 0;
            user-select: none;
        }

        h1 { margin-bottom: 10px; }

        .stats {
            display: flex;
            gap: 20px;
            margin-bottom: 20px;
            font-size: 1.2rem;
        }

        .game-board {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 10px;
            width: 320px;
            height: 320px;
        }

        .card {
            background-color: var(--card-bg);
            border-radius: 8px;
            cursor: pointer;
            position: relative;
            transform-style: preserve-3d;
            transition: transform 0.5s;
            box-shadow: 0 4px 6px rgba(0,0,0,0.3);
        }

        .card.flipped {
            transform: rotateY(180deg);
        }

        .card-face {
            position: absolute;
            width: 100%;
            height: 100%;
            backface-visibility: hidden;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 2rem;
            border-radius: 8px;
        }

        .card-front {
            background-color: var(--accent);
            color: white;
            font-weight: bold;
            font-size: 1.5rem;
        }

        .card-back {
            transform: rotateY(180deg);
            background-color: white;
        }

        .btn {
            margin-top: 20px;
            padding: 10px 20px;
            background-color: var(--accent);
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            font-size: 1rem;
            transition: background 0.3s;
        }

        .btn:hover { background-color: #c0354c; }

        /* Confetti Animation */
        @keyframes pop {
            0% { transform: scale(1); }
            50% { transform: scale(1.1); }
            100% { transform: scale(1); }
        }

        .matched { animation: pop 0.3s ease-in-out; }

        @media (min-width: 500px) {
            .game-board { width: 400px; height: 400px; }
        }
    </style>
</head>
<body>

    <h1>🚀 Space Catcher</h1>

    <div class="stats">
        <span>Moves: <span id="moves">0</span></span>
        <span>Pairs: <span id="pairs">0</span>/8</span>
    </div>

    <div class="game-board" id="gameBoard">
        <!-- Cards generated by JS -->
    </div>

    <button class="btn" onclick="restartGame()">Restart Game</button>

    <script>
        const items = ['🚀', '👽', '🛸', '🪐', '☄️', '🌑', '🔭', '👾'];
        let cards = [];
        let flippedCards = [];
        let matchedPairs = 0;
        let moves = 0;
        let lockBoard = false;

        const gameBoard = document.getElementById('gameBoard');
        const movesDisplay = document.getElementById('moves');
        const pairsDisplay = document.getElementById('pairs');

        function init() {
            // Create pairs and shuffle
            cards = [...items, ...items];
            cards.sort(() => 0.5 - Math.random());

            gameBoard.innerHTML = '';

            cards.forEach((emoji, index) => {
                const card = document.createElement('div');
                card.classList.add('card');
                card.dataset.emoji = emoji;
                card.dataset.index = index;

                const frontFace = document.createElement('div');
                frontFace.classList.add('card-face', 'card-front');
                frontFace.innerText = '?'; // Card back symbol

                const backFace = document.createElement('div');
                backFace.classList.add('card-face', 'card-back');
                backFace.innerText = emoji; // The hidden image

                card.appendChild(frontFace);
                card.appendChild(backFace);

                card.addEventListener('click', flipCard);
                gameBoard.appendChild(card);
            });
        }

        function flipCard() {
            if (lockBoard) return;
            if (this === flippedCards[0]) return; // Can't click same card twice

            this.classList.add('flipped');
            flippedCards.push(this);

            if (flippedCards.length === 2) {
                moves++;
                movesDisplay.innerText = moves;
                checkForMatch();
            }
        }

        function checkForMatch() {
            let isMatch = flippedCards[0].dataset.emoji === flippedCards[1].dataset.emoji;

            isMatch ? disableCards() : unflipCards();
        }

        function disableCards() {
            flippedCards[0].classList.add('matched');
            flippedCards[1].classList.add('matched');
            matchedPairs++;
            pairsDisplay.innerText = matchedPairs;
            flippedCards = [];

            if (matchedPairs === items.length) {
                setTimeout(() => alert(`You won in ${moves} moves! 🎉`), 500);
            }
        }

        function unflipCards() {
            lockBoard = true;
            setTimeout(() => {
                flippedCards[0].classList.remove('flipped');
                flippedCards[1].classList.remove('flipped');
                flippedCards = [];
                lockBoard = false;
            }, 1000);
        }

        function restartGame() {
            matchedPairs = 0;
            moves = 0;
            movesDisplay.innerText = 0;
            pairsDisplay.innerText = 0;
            flippedCards = [];
            lockBoard = false;
            init();
        }

        // Start the game on load
        init();
    </script>
</body>
</html>
```

### How to Play:
1.  **Copy** the code block above.
2.  Create a new file on your computer named `game.html`.
3.  **Paste** the code into that file and save it.
4.  **Double-click** `game.html` to open it in your browser.

### Why it's fun:
*   **Instant Play:** No installation required.
*   **Visual Clarity:** Uses emojis instead of images, so it loads instantly.
*   **Animations:** Cards flip smoothly, and a little "pop" effect happens when you match a pair.
*   **Responsive:** Works on different screen sizes.
